def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive_bids = []
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= DAILY_SALARY * 0.85:
                    aggressive_bids.append(float(bid))

    if not alive:
        return max(0.0, min(float(budget), DAILY_SALARY * 0.2))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0:
        supply_ratio = 0.0
    if supply_ratio > 1:
        supply_ratio = 1.0

    pressure = len(aggressive_bids)
    urgent = hp <= 2 or no_water >= 1
    very_urgent = hp <= 1 or no_water >= 2

    if very_urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif urgent:
        if pressure >= 2:
            target = max(DAILY_SALARY * 0.88, highest_prev + 1.0)
        else:
            target = max(DAILY_SALARY * 0.72, avg_prev + 1.5)
    else:
        if supply >= 22:
            target = DAILY_SALARY * 0.22
        elif supply >= 19:
            target = DAILY_SALARY * 0.34
        else:
            target = DAILY_SALARY * 0.48

        if pressure >= 2:
            target = min(target, DAILY_SALARY * 0.30)
        elif highest_prev > 0 and highest_prev < DAILY_SALARY * 0.65 and supply < 19:
            target = max(target, highest_prev + 1.0)

    if weak_opponents >= 1 and not urgent:
        target *= 0.92

    if day >= 8 and hp >= 4 and not urgent:
        target *= 0.9

    reserve_floor = DAILY_SALARY * 1.2 if hp > 2 else DAILY_SALARY * 0.4
    max_affordable = max(0.0, float(budget) - reserve_floor)
    if urgent:
        max_affordable = float(budget)

    bid = min(float(budget), target)
    if not urgent:
        bid = min(bid, max_affordable)

    if bid < 0:
        bid = 0.0

    if urgent and bid < DAILY_SALARY * 0.55 and budget >= DAILY_SALARY * 0.55:
        bid = DAILY_SALARY * 0.55

    return float(max(0.0, min(float(budget), bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive.append((opp_id, opp))

    def clamp_bid(x):
        if my_budget <= 0:
            return 0.0
        if x < 0:
            return 0.0
        if x > my_budget:
            return my_budget
        return float(x)

    if not alive:
        return clamp_bid(min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    for opp_id, opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate how aggressive the field was yesterday
    prev_max = max(prev_bids) if prev_bids else 0.0
    prev_avg = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Base target: if others were bidding very high, we must compete; otherwise undercut slightly.
    # Use supply to decide aggressiveness (higher supply => less need to overbid).
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Determine urgency from my HP/no-water streak
    urgency = 0.0
    if my_hp <= 2:
        urgency = 1.0
    elif my_hp <= 4:
        urgency = 0.7
    elif my_hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.2

    if my_no_water_days >= 2:
        urgency = max(urgency, 0.8)
    elif my_no_water_days == 1:
        urgency = max(urgency, 0.5)

    # Aggression factor based on yesterday's max bid
    # Alex/Eric high bids suggest competition; Cindy died with 0 bids => others likely won't go that low.
    if prev_max >= DAILY_SALARY * 1.35:
        # Very competitive yesterday; bid near the high end but still slightly undercut.
        base = DAILY_SALARY * (0.95 - 0.25 * supply_norm)
        # If my HP is okay, try to undercut the max by a bit.
        if urgency < 0.6:
            base = min(base, prev_max - 3.0)
    elif prev_max >= DAILY_SALARY * 0.85:
        base = DAILY_SALARY * (0.75 - 0.18 * supply_norm)
        if urgency < 0.6:
            base = min(base, prev_max - 2.0)
    else:
        # Field was mostly low; we can bid enough to secure water without overspending.
        base = DAILY_SALARY * (0.55 - 0.15 * supply_norm)
        if urgency > 0.7:
            base = DAILY_SALARY * (0.75 - 0.12 * supply_norm)

    # Ensure we don't bid too low when supply is low (more likely others contest)
    if supply <= float(WATER_REQ) + 6.0:
        base = max(base, DAILY_SALARY * 0.45)

    # Convert urgency into final bid scaling
    final_bid = base * (0.75 + 0.5 * urgency)

    # Safety: if budget is low, cap to a fraction to avoid running out in later days
    # but still react to urgency.
    if my_budget < DAILY_SALARY * 0.6:
        final_bid = min(final_bid, my_budget * (0.85 if urgency > 0.7 else 0.6))

    # Final clamp
    return clamp_bid(final_bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return float(min(my_status['budget'], 20.0))

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 70.0

    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], DAILY_SALARY * 1.2))

    if supply < WATER_REQ * (len(alive_opponents) + 1):
        return float(min(my_status['budget'], max(avg_prev * 1.05, DAILY_SALARY * 0.85)))

    return float(min(my_status['budget'], max(avg_prev * 0.9, DAILY_SALARY * 0.5)))
